int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end) {
    int ret = -EINVAL;
    void *pos = *p;
    __u8 type;
    __u16 version;
    struct ceph_auth_ticket_handler *handler;

    if (pos + sizeof(type) > end)
        goto out;

    type = ceph_decode_8(&pos);
    if (pos + sizeof(version) > end)
        goto out;

    version = ceph_decode_16(&pos);

    handler = ceph_get_auth_ticket_handler(type);
    if (!handler) {
        ret = -ENOTSUPP;
        goto out;
    }

    ret = handler->decode_ticket(ac, secret, &pos, end);
    if (ret < 0)
        goto out;

    ret = 0;
    ac->have_session_key = true;
    ac->session_key = secret;
    ac->ticket_blob = ceph_memdup(pos, end - pos);
    if (!ac->ticket_blob) {
        ret = -ENOMEM;
        goto out;
    }

out:
    *p = pos;
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end) {
  int ret = -EINVAL;

  if (!ac || !secret || !p || !end || *p > end) {
    return -EINVAL;
  }

  // Decode the ticket structure version and type
  uint8_t version;
  uint8_t type;
  void *start = *p;

  if ((start + 2) > end) {
    return -EINVAL;
  }

  version = ((uint8_t *)start)[0];
  type = ((uint8_t *)start)[1];

  // Advance pointer
  *p = start + 2;

  // Retrieve the appropriate ticket handler
  struct ceph_auth_ticket_handler *handler =
      ceph_get_ticket_handler(ac, type, version);
  if (!handler) {
    return -ENOENT;
  }

  // Decrypt the ticket data
  struct ceph_buffer *decrypted =
      ceph_decrypt_ticket_data(secret, *p, end);
  if (!decrypted) {
    return -EIO;
  }

  // Update session key and ticket blob
  if (ceph_validate_ticket(decrypted)) {
    // Update the session key
    ret = ceph_update_session_key(ac, decrypted);
    if (ret < 0) {
      ceph_buffer_put(decrypted);
      return ret;
    }

    // Update the ticket blob
    ret = ceph_update_ticket_blob(ac, decrypted);
  } else {
    ret = -EINVAL;
  }

  ceph_buffer_put(decrypted);

  return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    uint8_t type, version;
    struct ceph_auth_ticket *ticket = NULL;

    if (!ac || !secret || !p || !*p || !end) {
        return -EINVAL;
    }

    if (ceph_decode_skip(&p, end, NULL, NULL) < 0)
        goto out;

    ceph_decode_8_safe(&p, end, type);
    ceph_decode_8_safe(&p, end, version);

    ticket = kmalloc(sizeof(*ticket), GFP_NOFS);
    if (!ticket)
        goto out;

    if (ceph_auth_client_get_ticket(ac, type, version, secret, &ticket->data, &ticket->data_len, &p, end)) {
        ret = -EIO;
        goto out;
    }

    if (ticket->valid_after || ticket->valid_until) {
        if (time_after(jiffies, ticket->valid_until)) {
            ret = -ETIMEDOUT;
            goto out;
        }
    }

    if (ceph_crypto_key_update(&ac->session_key, ticket->data, ticket->data_len)) {
        ret = -EKEYREJECTED;
        goto out;
    }

    ac->ticket_blob = kmemdup(ticket->data, ticket->data_len, GFP_NOFS);
    if (!ac->ticket_blob) {
        ret = -ENOMEM;
        goto out;
    }
    ac->ticket_blob_len = ticket->data_len;
    ret = 0;

out:
    kfree(ticket);
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int err = 0;
    uint32_t type, version;

    // decode ticket type and version
    if ((err = ceph_decode_32(p, end, &type)) < 0)
        return err;
    if ((err = ceph_decode_32(p, end, &version)) < 0)
        return err;

    // retrieve handler based on type and version
    struct ceph_auth_ticket_handler *handler = ceph_get_ticket_handler(type, version);
    if (!handler)
        return -EINVAL;

    // decrypt ticket data
    if ((err = handler->decrypt_ticket(ac, secret, p, end)) < 0)
        return err;

    // update session key and ticket blob
    if ((err = handler->update_session_key(ac, secret, p, end)) < 0)
        return err;

    return 0;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    u8 type;
    u8 version;
    struct ceph_auth_ticket *ticket;

    if (!ac || !secret || !p || !end || *p >= end) {
        return ret;
    }

    if ((end - *p) < sizeof(type) + sizeof(version)) {
        return ret;
    }

    type = **(u8**)p;
    (*p) += sizeof(type);

    version = **(u8**)p;
    (*p) += sizeof(version);

    ticket = ceph_auth_ticket_get_handler(ac, type, version);
    if (!ticket) {
        return ret;
    }

    ret = ticket->decode(ticket, p, end, secret);
    if (ret < 0) {
        goto out;
    }

    if (ticket->is_valid(ticket)) {
        ceph_update_session_key(ac, &ticket->session_key);
        ceph_set_ticket_blob(ac, &ticket->blob);
    } else {
        ret = -ETIME;
        goto out;
    }

    ret = 0;
out:
    ceph_auth_ticket_put(ticket);
    return ret;
}
